INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(1400, 'necessary', '/ˈnɛsəsɛri/', 'adjective', '{"zh-TW":["必要的"],"en":["needed; essential"]}', NULL, 'if necessary / necessary steps', '[{"en":"Take the necessary steps to fix this.","zh-TW":"採取必要措施來解決這個問題。"},{"en":"Overtime is sometimes necessary.","zh-TW":"加班有時是必要的。"}]', '{"adjective":"necessary","noun":"necessity","adverb":"necessarily","adjective2":"unnecessary"}', NULL, 3, 1400),
(1401, 'neck', '/nɛk/', 'noun', '{"zh-TW":["脖子"],"en":["the part connecting the head to the body"]}', NULL, 'neck and neck / bottleneck', '[{"en":"The two companies are neck and neck.","zh-TW":"兩家公司不相上下。"},{"en":"Shipping is the bottleneck in our process.","zh-TW":"運輸是我們流程中的瓶頸。"}]', '{"noun":"neck","noun2":"necklace","noun3":"bottleneck"}', NULL, 1, 1401),
(1402, 'need', '/niːd/', 'verb', '{"zh-TW":["需要"],"en":["to require something"]}', NULL, 'in need of / need to', '[{"en":"We are in need of more staff.","zh-TW":"我們需要更多員工。"},{"en":"You need to sign this form.","zh-TW":"你需要簽署這份表格。"}]', '{"verb":"need","noun":"need","adjective":"needy","adjective2":"needless"}', NULL, 1, 1402),
(1403, 'neglect', '/nɪˈɡlekt/', 'verb, noun', '{"zh-TW":["忽略；疏忽"],"en":["to fail to care for or attend to"]}', NULL, 'neglect duties/responsibilities / suffer from neglect', '[{"en":"He neglected to inform the team about the change.","zh-TW":"他疏忽了通知團隊有關變更的事。"},{"en":"The equipment suffered from years of neglect.","zh-TW":"設備因多年疏於維護而受損。"}]', '{"noun":"neglect, negligence","verb":"neglect","adjective":"negligent"}', NULL, 3, 1403),
(1404, 'negotiate', '/nɪˈɡoʊʃieɪt/', 'verb', '{"zh-TW":["談判；協商","磋商","協商"],"en":["to try to reach an agreement through discussion","to discuss to reach an agreement","to deal with something","to reach an agreement through discussion"]}', '{"prefix":{"text":"neg-","meaning":"not (不)"},"root":{"text":"oti","meaning":"leisure (閒暇)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"非閒暇之事（嚴肅處理），即「談判」。"}', 'negotiate a deal / negotiate terms / negotiate a contract; negotiate with sb. / negotiate a deal; negotiate terms / negotiate a salary', '[{"en":"The two sides are negotiating a peace agreement.","zh-TW":"雙方正在協商和平協議。"},{"en":"She negotiated a higher salary.","zh-TW":"她談判爭取到了更高的薪水。"},{"en":"The union is negotiating with management for better wages.","zh-TW":"工會正在與管理層協商更高的薪資。"},{"en":"We negotiated a 10% discount.","zh-TW":"我們談成了九折優惠。"},{"en":"She successfully negotiated better terms.","zh-TW":"她成功談成了更好的條件。"},{"en":"New hires can negotiate their salary.","zh-TW":"新員工可以協商薪資。"}]', '{"noun":"negotiation","noun2":"negotiator","adjective":"negotiable"}', NULL, 3, 1404),
(1405, 'neighbor', '/ˈneɪbər/', 'noun', '{"zh-TW":["鄰居"],"en":["a person living next door or nearby"]}', NULL, 'next-door neighbor / neighborhood', '[{"en":"Our office neighbors are a law firm.","zh-TW":"我們辦公室的鄰居是一家律師事務所。"},{"en":"It is a friendly neighborhood for business.","zh-TW":"這是一個對商業友好的社區。"}]', '{"noun":"neighbor","noun2":"neighborhood","adjective":"neighboring"}', NULL, 3, 1405),
(1406, 'nervous', '/ˈnɜːrvəs/', 'adjective', '{"zh-TW":["緊張的；神經質的"],"en":["easily worried or anxious"]}', '{"root":{"text":"nerv","meaning":"nerve (神經)"},"suffix":{"text":"-ous","meaning":"full of (充滿)"},"logic":"神經緊繃的，即「緊張的」。"}', 'feel nervous / nervous about', '[{"en":"She was nervous before the presentation.","zh-TW":"她在報告前很緊張。"},{"en":"I always get nervous during exams.","zh-TW":"我考試時總是很緊張。"}]', '{"noun":"nervousness","adverb":"nervously"}', NULL, 3, 1406),
(1407, 'net', '/nɛt/', 'adjective', '{"zh-TW":["淨的；純的"],"en":["remaining after deductions"]}', '{"root":{"text":"net","meaning":"clean (乾淨的)"}}', 'net profit / net income / net worth', '[{"en":"The company reported a net profit of $2 million.","zh-TW":"公司報告了兩百萬美元的淨利潤。"},{"en":"What is your net income after taxes?","zh-TW":"你扣稅後的淨收入是多少？"}]', '{"noun":"net","verb":"net"}', NULL, 1, 1407),
(1408, 'network', '/ˈnɛtwɜːrk/', 'noun', '{"zh-TW":["網路；人脈","網路；網絡","人脈"],"en":["a system of connected computers or people","a system of connected things","a group exchanging information"]}', '{"root":{"text":"net","meaning":"mesh (網)"},"suffix":{"text":"work","meaning":"結構"}}', 'social network / network connection; build a network / social network', '[{"en":"The network is down.","zh-TW":"網路斷了。"},{"en":"Networking is important for your career.","zh-TW":"建立人脈對職業很重要。"},{"en":"She built an extensive professional network.","zh-TW":"她建立了廣泛的專業人脈。"},{"en":"The company is upgrading its computer network.","zh-TW":"公司正在升級電腦網路。"}]', '{"verb":"network","noun2":"networking","noun":"networking, networker"}', NULL, 3, 1408),
(1409, 'neutral', '/ˈnjuːtrəl/', 'adjective', '{"zh-TW":["中立的","中性的"],"en":["not supporting either side","without strong characteristics"]}', '{"root":{"text":"neutr","meaning":"neither (都不)"},"suffix":{"text":"-al","meaning":"...的"}}', 'remain neutral / neutral position', '[{"en":"The mediator must remain neutral.","zh-TW":"調解人必須保持中立。"},{"en":"Please use a neutral tone in the email.","zh-TW":"請在郵件中使用中性語氣。"}]', '{"noun":"neutrality","verb":"neutralize","adverb":"neutrally"}', NULL, 3, 1409),
(1410, 'nevertheless', '/ˌnɛvərðəˈlɛs/', 'adverb', '{"zh-TW":["然而；儘管如此"],"en":["in spite of that; however"]}', NULL, 'nevertheless, ... / but nevertheless', '[{"en":"The project was risky; nevertheless, we proceeded.","zh-TW":"項目有風險；然而我們繼續了。"},{"en":"He was tired; nevertheless, he finished the report.","zh-TW":"他很累；儘管如此他完成了報告。"}]', NULL, NULL, 4, 1410),
(1411, 'news', '/njuːz/', 'noun', '{"zh-TW":["新聞；消息"],"en":["new information about recent events"]}', NULL, 'breaking news / good news', '[{"en":"I have good news about the contract.","zh-TW":"我有關於合約的好消息。"},{"en":"The news spread quickly across the company.","zh-TW":"消息在公司內迅速傳開。"}]', '{"noun":"news","noun2":"newspaper","noun3":"newsletter","adjective":"newsworthy"}', NULL, 1, 1411),
(1412, 'nice', '/naɪs/', 'adjective', '{"zh-TW":["好的；友善的"],"en":["pleasant; agreeable"]}', NULL, 'nice to meet you / nice work', '[{"en":"Nice to meet you.","zh-TW":"很高興認識你。"},{"en":"Nice work on the presentation!","zh-TW":"簡報做得好！"}]', '{"adjective":"nice","adverb":"nicely"}', NULL, 1, 1412),
(1413, 'night', '/naɪt/', 'noun', '{"zh-TW":["夜晚"],"en":["the time when it is dark"]}', NULL, 'night shift / overnight', '[{"en":"Some staff work the night shift.","zh-TW":"有些員工上夜班。"},{"en":"We can ship it overnight.","zh-TW":"我們可以隔夜寄送。"}]', '{"noun":"night","adjective":"nightly","adverb":"overnight"}', NULL, 2, 1413),
(1414, 'noise', '/nɔɪz/', 'noun', '{"zh-TW":["噪音；雜訊"],"en":["unwanted sound"]}', NULL, 'make noise / noise pollution', '[{"en":"Noise pollution affects worker productivity.","zh-TW":"噪音污染影響工人生產力。"},{"en":"The data contains too much noise.","zh-TW":"數據中有太多雜訊。"}]', '{"noun":"noise","adjective":"noisy","adverb":"noisily"}', NULL, 2, 1414),
(1415, 'nominal', '/ˈnɒmɪnəl/', 'adjective', '{"zh-TW":["名義上的","象徵性的"],"en":["in name only","very small"]}', '{"root":{"text":"nomin","meaning":"name (名字)"},"suffix":{"text":"-al","meaning":"...的"}}', 'nominal fee / nominal value', '[{"en":"They charge a nominal fee for the service.","zh-TW":"他們收取象徵性費用。"},{"en":"He is the nominal leader of the organization.","zh-TW":"他是名義上的領導人。"}]', '{"adverb":"nominally","verb":"nominate","noun":"nomination"}', NULL, 3, 1415),
(1416, 'nominate', '/ˈnɒmɪneɪt/', 'verb', '{"zh-TW":["提名；任命"],"en":["to suggest someone for a position"]}', '{"root":{"text":"nomin","meaning":"name (名字)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'nominate sb. for / be nominated', '[{"en":"She was nominated for Employee of the Year.","zh-TW":"她被提名為年度最佳員工。"},{"en":"The board nominated him as chairman.","zh-TW":"董事會提名他為主席。"}]', '{"noun":"nomination, nominee","adjective":"nominal"}', NULL, 3, 1416),
(1417, 'norm', '/nɔːrm/', 'noun', '{"zh-TW":["規範；標準","常態"],"en":["a standard","the usual state"]}', '{"root":{"text":"norm","meaning":"rule (規則)"}}', 'social norm / above the norm', '[{"en":"Working from home has become the norm.","zh-TW":"在家工作已成為常態。"},{"en":"Safety standards exceed industry norms.","zh-TW":"安全標準超過行業規範。"}]', '{"adjective":"normal, normative","verb":"normalize","adverb":"normally"}', NULL, 1, 1417),
(1418, 'normal', '/ˈnɔːrməl/', 'adjective', '{"zh-TW":["正常的；一般的","正常的"],"en":["usual; typical; expected","usual; typical"]}', '{"root":{"text":"norm","meaning":"rule (規則)"},"suffix":{"text":"-al","meaning":"...的"}}', 'return to normal / normal procedure; return to normal / normal hours / new normal', '[{"en":"Business operations have returned to normal.","zh-TW":"業務運營已恢復正常。"},{"en":"This is normal procedure for new hires.","zh-TW":"這是新員工的正常流程。"},{"en":"Business hours have returned to normal.","zh-TW":"營業時間已恢復正常。"},{"en":"Remote work is the new normal.","zh-TW":"遠程工作是新常態。"}]', '{"noun":"normality, norm","verb":"normalize","adverb":"normally"}', NULL, 2, 1418),
(1419, 'north', '/nɔːrθ/', 'noun', '{"zh-TW":["北方"],"en":["the direction opposite to south"]}', NULL, 'north of / up north', '[{"en":"The factory is north of the city.","zh-TW":"工廠在城市北邊。"},{"en":"We are expanding up north.","zh-TW":"我們正在向北方擴展。"}]', '{"noun":"north","adjective":"northern","adverb":"northward"}', NULL, 2, 1419),
(1420, 'notable', '/ˈnoʊtəbl/', 'adjective', '{"zh-TW":["值得注意的；顯著的"],"en":["worthy of attention; remarkable"]}', '{"root":{"text":"not","meaning":"mark (標記)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'notable achievement / most notably', '[{"en":"There has been a notable improvement in sales.","zh-TW":"銷售額有顯著改善。"},{"en":"The city is notable for its architecture.","zh-TW":"這城市以建築聞名。"}]', '{"adverb":"notably","noun":"notability"}', NULL, 3, 1420),
(1421, 'note', '/noʊt/', 'noun', '{"zh-TW":["筆記；注意"],"en":["a short written message","to pay attention to"]}', NULL, 'take note / please note', '[{"en":"Please note the new office hours.","zh-TW":"請注意新的辦公時間。"},{"en":"I took notes during the meeting.","zh-TW":"我在會議中做了筆記。"}]', '{"noun":"note","verb":"note","adjective":"noteworthy","noun2":"notebook"}', NULL, 1, 1421),
(1422, 'notice', '/ˈnoʊtɪs/', 'noun', '{"zh-TW":["通知；公告","注意"],"en":["a written announcement","attention"]}', '{"root":{"text":"not","meaning":"know (知道)"},"suffix":{"text":"-ice","meaning":"名詞後綴"}}', 'give notice / at short notice / until further notice', '[{"en":"Please give two weeks'' notice before resigning.","zh-TW":"辭職前請提前兩週通知。"},{"en":"The change takes effect until further notice.","zh-TW":"變更持續有效直到另行通知。"}]', '{"adjective":"noticeable","adverb":"noticeably","verb":"notice"}', NULL, 2, 1422),
(1423, 'notify', '/ˈnoʊtɪfaɪ/', 'verb', '{"zh-TW":["通知；告知"],"en":["to formally inform someone"]}', '{"root":{"text":"not","meaning":"know (知道)"},"suffix":{"text":"-ify","meaning":"使...化"}}', 'notify sb. of sth. / notify in writing', '[{"en":"We will notify you of any schedule changes.","zh-TW":"我們會通知您時間表的變更。"},{"en":"All employees must be notified in advance.","zh-TW":"所有員工必須提前被通知。"}]', '{"noun":"notification","adjective":"notifiable"}', NULL, 2, 1423),
(1424, 'notion', '/ˈnoʊʃən/', 'noun', '{"zh-TW":["概念；想法"],"en":["a concept or belief"]}', '{"root":{"text":"not","meaning":"know (知道)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'the notion that / preconceived notion', '[{"en":"She rejected the notion that women cannot lead.","zh-TW":"她駁斥了女性不能領導的觀念。"},{"en":"He has no notion of the difficulty.","zh-TW":"他不知道有多困難。"}]', '{"adjective":"notional"}', NULL, 2, 1424),
(1425, 'notwithstanding', '/ˌnɒtwɪθˈstændɪŋ/', 'preposition', '{"zh-TW":["儘管；雖然"],"en":["in spite of; despite"]}', NULL, 'notwithstanding the fact that', '[{"en":"Notwithstanding the challenges, it was completed on time.","zh-TW":"儘管有挑戰，仍按時完成。"},{"en":"The contract is valid notwithstanding minor errors.","zh-TW":"儘管有小錯，合約仍有效。"}]', NULL, NULL, 5, 1425),
(1426, 'novel', '/ˈnɒvəl/', 'adjective', '{"zh-TW":["新穎的；新奇的"],"en":["new and original"]}', '{"root":{"text":"nov","meaning":"new (新的)"},"suffix":{"text":"-el","meaning":"後綴"}}', 'novel approach / novel idea', '[{"en":"The team proposed a novel approach.","zh-TW":"團隊提出了新穎的方法。"},{"en":"This is a novel concept in marketing.","zh-TW":"這是行銷的新穎概念。"}]', '{"noun":"novelty, novelist"}', NULL, 2, 1426),
(1427, 'number', '/ˈnʌmbər/', 'noun', '{"zh-TW":["數字；號碼"],"en":["a mathematical value","a quantity"]}', NULL, 'a number of / phone number', '[{"en":"A number of clients have complained.","zh-TW":"許多客戶投訴了。"},{"en":"What is your phone number?","zh-TW":"你的電話號碼是什麼？"}]', '{"noun":"number","verb":"number","adjective":"numerous","adjective2":"numerical"}', NULL, 2, 1427),
(1428, 'numerous', '/ˈnjuːmərəs/', 'adjective', '{"zh-TW":["許多的；眾多的"],"en":["great in number; many"]}', '{"root":{"text":"numer","meaning":"number (數字)"},"suffix":{"text":"-ous","meaning":"充滿...的"}}', 'numerous occasions / numerous studies', '[{"en":"The company received numerous complaints.","zh-TW":"公司收到大量投訴。"},{"en":"She published numerous articles.","zh-TW":"她發表了許多文章。"}]', '{"adverb":"numerously","noun":"number"}', NULL, 3, 1428),
(1429, 'nurse', '/nɜːrs/', 'noun', '{"zh-TW":["護士"],"en":["a person trained to care for sick people"]}', NULL, 'registered nurse / nurse practitioner', '[{"en":"The company clinic has two registered nurses.","zh-TW":"公司診所有兩位註冊護士。"},{"en":"She trained as a nurse before going into management.","zh-TW":"她在從事管理工作前受過護士訓練。"}]', '{"noun":"nurse","noun2":"nursing","verb":"nurse"}', NULL, 2, 1429),
(1430, 'nurture', '/ˈnɜːrtʃər/', 'verb', '{"zh-TW":["培養；養育"],"en":["to care for and encourage growth"]}', '{"root":{"text":"nutr","meaning":"nourish (滋養)"},"suffix":{"text":"-ure","meaning":"行為"}}', 'nurture talent / nurture relationships', '[{"en":"The manager nurtures young talent.","zh-TW":"經理培養年輕人才。"},{"en":"Nurture good relationships with clients.","zh-TW":"培養與客戶的良好關係。"}]', '{"noun":"nurture, nurturer","adjective":"nurturing"}', NULL, 3, 1430),
(1431, 'oath', '/oʊθ/', 'noun', '{"zh-TW":["宣誓；誓言"],"en":["a formal promise to tell the truth"]}', NULL, 'take an oath / under oath', '[{"en":"She took an oath of office.","zh-TW":"她進行了就職宣誓。"},{"en":"He lied under oath.","zh-TW":"他在宣誓後說謊。"}]', NULL, NULL, 1, 1431),
(1432, 'obey', '/oʊˈbeɪ/', 'verb', '{"zh-TW":["服從；遵守"],"en":["to do what you are told"]}', '{"prefix":{"text":"ob-","meaning":"toward"},"root":{"text":"ey","meaning":"hear"}}', 'obey the rules / obey orders', '[{"en":"All employees must obey company regulations.","zh-TW":"所有員工必須遵守公司規定。"},{"en":"Citizens are expected to obey the law.","zh-TW":"公民應遵守法律。"}]', '{"noun":"obedience","adjective":"obedient","adverb":"obediently"}', NULL, 1, 1432),
(1433, 'object', '/əbˈdʒɛkt/', 'verb', '{"zh-TW":["反對"],"en":["to express disagreement"]}', '{"prefix":{"text":"ob-","meaning":"against"},"root":{"text":"ject","meaning":"throw (投擲)"}}', 'object to sth.', '[{"en":"Several members objected to the proposal.","zh-TW":"幾位成員反對該提案。"},{"en":"No one objected to the new policy.","zh-TW":"沒人反對新政策。"}]', '{"noun":"objection, object","adjective":"objectionable"}', NULL, 2, 1433),
(1434, 'objective', '/əbˈdʒɛktɪv/', 'noun', '{"zh-TW":["目標；目的"],"en":["a goal or aim"]}', '{"prefix":{"text":"ob-","meaning":"toward"},"root":{"text":"ject","meaning":"throw"},"suffix":{"text":"-ive","meaning":"...的"}}', 'meet an objective / objective assessment', '[{"en":"Our main objective is to increase market share.","zh-TW":"我們的主要目標是增加市場份額。"},{"en":"Try to remain objective when evaluating.","zh-TW":"評估時請保持客觀。"}]', '{"noun":"objectivity","adverb":"objectively"}', NULL, 3, 1434),
(1435, 'obligation', '/ˌɒblɪˈɡeɪʃən/', 'noun', '{"zh-TW":["義務；責任"],"en":["something you must do"]}', '{"root":{"text":"oblig","meaning":"bind (綁定)"},"suffix":{"text":"-ation","meaning":"狀態"}}', 'legal obligation / under no obligation', '[{"en":"You are under no obligation to accept.","zh-TW":"你沒有義務接受。"},{"en":"The company has an obligation to shareholders.","zh-TW":"公司對股東有責任。"}]', '{"verb":"oblige","adjective":"obligatory, obliging"}', NULL, 4, 1435),
(1436, 'observe', '/əbˈzɜːrv/', 'verb', '{"zh-TW":["觀察","遵守"],"en":["to watch carefully","to obey a rule"]}', '{"prefix":{"text":"ob-","meaning":"over"},"root":{"text":"serv","meaning":"watch (看)"}}', 'observe changes / observe rules', '[{"en":"Scientists observed a significant change.","zh-TW":"科學家觀察到顯著變化。"},{"en":"All visitors must observe safety regulations.","zh-TW":"訪客必須遵守安全規定。"}]', '{"noun":"observation, observer","adjective":"observant, observable"}', NULL, 3, 1436),
(1437, 'obsolete', '/ˈɒbsəliːt/', 'adjective', '{"zh-TW":["過時的；淘汰的"],"en":["no longer in use"]}', '{"prefix":{"text":"ob-","meaning":"away"},"root":{"text":"sol","meaning":"use (使用)"}}', 'become obsolete / obsolete technology', '[{"en":"This software has become obsolete.","zh-TW":"這個軟體已經過時。"},{"en":"New technology rendered the old system obsolete.","zh-TW":"新技術使舊系統過時。"}]', '{"noun":"obsolescence"}', NULL, 3, 1437),
(1438, 'obstacle', '/ˈɒbstəkl/', 'noun', '{"zh-TW":["障礙"],"en":["something that blocks progress"]}', '{"prefix":{"text":"ob-","meaning":"against"},"root":{"text":"sta","meaning":"stand (站)"}}', 'overcome an obstacle / major obstacle', '[{"en":"Lack of funding is a major obstacle.","zh-TW":"缺乏資金是主要障礙。"},{"en":"She overcame many obstacles.","zh-TW":"她克服了許多障礙。"}]', NULL, NULL, 3, 1438),
(1439, 'obtain', '/əbˈteɪn/', 'verb', '{"zh-TW":["獲得；取得"],"en":["to get or acquire something","to get something by effort"]}', '{"prefix":{"text":"ob-","meaning":"toward (朝向)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"朝向持有而得到，即「獲得」。"}', 'obtain permission / obtain information / obtain a degree', '[{"en":"You must obtain permission before entering.","zh-TW":"進入前必須獲得許可。"},{"en":"She obtained her PhD from Harvard.","zh-TW":"她從哈佛取得了博士學位。"},{"en":"You must obtain approval before proceeding.","zh-TW":"你必須獲得批准才能繼續。"},{"en":"Details can be obtained from our website.","zh-TW":"詳情可從網站獲取。"}]', '{"adjective":"obtainable"}', NULL, 2, 1439),
(1440, 'obvious', '/ˈɒbviəs/', 'adjective', '{"zh-TW":["明顯的"],"en":["easy to see or understand"]}', '{"prefix":{"text":"ob-","meaning":"in the way"},"root":{"text":"vi","meaning":"way (路)"},"suffix":{"text":"-ous","meaning":"...的"}}', 'obvious reason / it is obvious that', '[{"en":"It is obvious that we need to cut costs.","zh-TW":"很明顯我們需要削減成本。"},{"en":"The answer was obvious to everyone.","zh-TW":"答案對所有人都顯而易見。"}]', '{"adverb":"obviously","noun":"obviousness"}', NULL, 3, 1440),
(1441, 'occasion', '/əˈkeɪʒən/', 'noun', '{"zh-TW":["場合；時機"],"en":["a particular time or event"]}', '{"prefix":{"text":"oc-","meaning":"toward"},"root":{"text":"cas","meaning":"fall (落)"}}', 'on this occasion / special occasion / on occasion', '[{"en":"On this occasion, we will make an exception.","zh-TW":"這次我們將破例。"},{"en":"The dinner was a formal occasion.","zh-TW":"晚餐是正式場合。"}]', '{"adjective":"occasional","adverb":"occasionally"}', NULL, 3, 1441),
(1442, 'occupy', '/ˈɒkjupaɪ/', 'verb', '{"zh-TW":["占據；使忙碌","佔據","使忙碌"],"en":["to fill or take up a space or time","to fill or take up space","to keep busy"]}', '{"prefix":{"text":"oc-","meaning":"over (在上)"},"root":{"text":"cupy","meaning":"seize (佔有)"},"logic":"佔有其上，即「占據」。"}', 'occupy a position / occupy space / occupied with; occupy a position / be occupied with', '[{"en":"The meeting occupied the entire morning.","zh-TW":"會議佔了整個早上。"},{"en":"She is occupied with work right now.","zh-TW":"她現在忙於工作。"},{"en":"The department occupies the entire third floor.","zh-TW":"部門佔據了整個三樓。"},{"en":"She has been occupied with the merger.","zh-TW":"她一直忙於合併事宜。"}]', '{"noun":"occupation","adjective":"occupied"}', NULL, 2, 1442),
(1443, 'occur', '/əˈkɜːr/', 'verb', '{"zh-TW":["發生","想到"],"en":["to happen","to come into mind"]}', '{"prefix":{"text":"oc-","meaning":"toward"},"root":{"text":"cur","meaning":"run (跑)"}}', 'occur frequently / it occurs to sb.', '[{"en":"The error occurred during the update.","zh-TW":"錯誤發生在更新期間。"},{"en":"It never occurred to me to check.","zh-TW":"我從未想到要檢查。"}]', '{"noun":"occurrence"}', NULL, 2, 1443),
(1444, 'ocean', '/ˈoʊʃən/', 'noun', '{"zh-TW":["海洋"],"en":["a very large area of sea"]}', NULL, 'ocean freight / across the ocean', '[{"en":"Ocean freight is cheaper than air freight.","zh-TW":"海運比空運便宜。"},{"en":"Our products ship across the ocean.","zh-TW":"我們的產品跨洋運送。"}]', '{"noun":"ocean","adjective":"oceanic"}', NULL, 2, 1444),
(1445, 'offer', '/ˈɒfər/', 'noun', '{"zh-TW":["提議；出價；優惠","提供；提議"],"en":["something proposed or available","a reduced price for a limited time","to present for acceptance"]}', '{"prefix":{"text":"of-","meaning":"toward (朝向)"},"root":{"text":"fer","meaning":"carry (帶來)"},"logic":"帶向某人，即「提供」。"}', 'special offer / make an offer; offer a discount / job offer / make an offer', '[{"en":"The store has a special offer on electronics.","zh-TW":"這家店有電子產品特惠。"},{"en":"He made an offer on the house.","zh-TW":"他對那棟房子出了價。"},{"en":"They offered me a position in marketing.","zh-TW":"他們給我一個行銷職位。"},{"en":"We offer a 15% discount on bulk orders.","zh-TW":"大量訂購可享15%折扣。"}]', '{"verb":"offer","noun":"offer, offering"}', NULL, 2, 1445),
(1446, 'office', '/ˈɒfɪs/', 'noun', '{"zh-TW":["辦公室"],"en":["a place where business work is done"]}', NULL, 'head office / office supplies', '[{"en":"Our head office is in Taipei.","zh-TW":"我們的總部在台北。"},{"en":"Order office supplies from the catalog.","zh-TW":"從目錄訂購辦公用品。"}]', '{"noun":"office","noun2":"officer","adjective":"official","adverb":"officially"}', NULL, 2, 1446),
(1447, 'offset', '/ˈɒfsɛt/', 'verb', '{"zh-TW":["抵消；彌補"],"en":["to balance or compensate"]}', '{"prefix":{"text":"off-","meaning":"away"},"root":{"text":"set","meaning":"place (放)"}}', 'offset costs / offset losses', '[{"en":"The gains offset the earlier losses.","zh-TW":"收益抵消了早期損失。"},{"en":"Higher sales offset increased costs.","zh-TW":"更高銷售額抵消了成本增加。"}]', '{"noun":"offset"}', NULL, 2, 1447),
(1448, 'old', '/oʊld/', 'adjective', '{"zh-TW":["舊的；老的"],"en":["having existed for a long time","of a particular age"]}', NULL, 'years old / old-fashioned', '[{"en":"The building is 50 years old.","zh-TW":"這棟大樓有50年歷史。"},{"en":"That approach is old-fashioned now.","zh-TW":"那個方法現在已經過時了。"}]', '{"adjective":"old","noun":"age","verb":"age"}', NULL, 1, 1448),
(1449, 'ongoing', '/ˈɒnɡoʊɪŋ/', 'adjective', '{"zh-TW":["持續進行的"],"en":["continuing; still in progress"]}', NULL, 'ongoing process / ongoing project', '[{"en":"The investigation is still ongoing.","zh-TW":"調查仍在進行中。"},{"en":"We provide ongoing training for staff.","zh-TW":"我們提供持續培訓。"}]', NULL, NULL, 3, 1449);
