(1450, 'open', '/ˈoʊpən/', 'adjective', '{"zh-TW":["開放的；公開的"],"en":["not closed","available to everyone"]}', NULL, 'open position / open-minded', '[{"en":"We have an open position in marketing.","zh-TW":"我們行銷部有一個空缺職位。"},{"en":"Be open-minded about new ideas.","zh-TW":"對新想法保持開放的心態。"}]', '{"adjective":"open","verb":"open","noun":"opening","adverb":"openly"}', NULL, 1, 1450),
(1451, 'operate', '/ˈɒpəreɪt/', 'verb', '{"zh-TW":["操作；運作","經營"],"en":["to work or function","to manage"]}', '{"root":{"text":"oper","meaning":"work (工作)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'operate a business / operate machinery', '[{"en":"The company operates in over 30 countries.","zh-TW":"公司在30多國經營。"},{"en":"Only trained staff should operate this.","zh-TW":"只有培訓過的人員能操作。"}]', '{"noun":"operation, operator","adjective":"operational, operative"}', NULL, 3, 1451),
(1452, 'opinion', '/əˈpɪnjən/', 'noun', '{"zh-TW":["意見；看法"],"en":["a personal belief or judgment"]}', '{"root":{"text":"opin","meaning":"think (認為)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'in my opinion / public opinion', '[{"en":"In my opinion, we should postpone the launch.","zh-TW":"我認為應推遲發布。"},{"en":"Public opinion is shifting.","zh-TW":"民意正在轉變。"}]', '{"adjective":"opinionated"}', NULL, 3, 1452),
(1453, 'opponent', '/əˈpoʊnənt/', 'noun', '{"zh-TW":["對手；反對者"],"en":["one who competes against"]}', '{"prefix":{"text":"op-","meaning":"against"},"root":{"text":"pon","meaning":"put (放)"},"suffix":{"text":"-ent","meaning":"人"}}', 'political opponent / defeat an opponent', '[{"en":"Our main opponent is a multinational firm.","zh-TW":"我們的主要對手是跨國公司。"},{"en":"She defeated her opponent.","zh-TW":"她擊敗了對手。"}]', '{"verb":"oppose","noun":"opposition","adjective":"opposing"}', NULL, 3, 1453),
(1454, 'opportunity', '/ˌɒpərˈtjuːnɪti/', 'noun', '{"zh-TW":["機會"],"en":["a chance to do something"]}', '{"root":{"text":"portun","meaning":"port (港口)"},"suffix":{"text":"-ity","meaning":"狀態"}}', 'seize an opportunity / job opportunity', '[{"en":"This internship is a great opportunity.","zh-TW":"這實習是個好機會。"},{"en":"Seize every opportunity to expand.","zh-TW":"抓住每個擴展機會。"}]', '{"adjective":"opportune","noun":"opportunist"}', NULL, 4, 1454),
(1455, 'oppose', '/əˈpoʊz/', 'verb', '{"zh-TW":["反對；對抗"],"en":["to disagree with or resist"]}', '{"prefix":{"text":"op-","meaning":"against"},"root":{"text":"pos","meaning":"put (放)"}}', 'oppose a plan / as opposed to', '[{"en":"Several senators opposed the legislation.","zh-TW":"幾位參議員反對立法。"},{"en":"As opposed to last year, profits increased.","zh-TW":"與去年相反，利潤增加了。"}]', '{"noun":"opposition","adjective":"opposite, opposing"}', NULL, 2, 1455),
(1456, 'opt', '/ɒpt/', 'verb', '{"zh-TW":["選擇；決定"],"en":["to make a choice"]}', '{"root":{"text":"opt","meaning":"choose (選)"}}', 'opt for / opt out / opt in', '[{"en":"Many employees opted for early retirement.","zh-TW":"許多員工選擇提前退休。"},{"en":"You can opt out of the mailing list.","zh-TW":"你可以退出郵件列表。"}]', '{"noun":"option","adjective":"optional"}', NULL, 1, 1456),
(1457, 'optimistic', '/ˌɒptɪˈmɪstɪk/', 'adjective', '{"zh-TW":["樂觀的"],"en":["hopeful and confident about the future"]}', '{"root":{"text":"optim","meaning":"best (最好)"},"suffix":{"text":"-istic","meaning":"characterized by (以…為特徵)"},"logic":"以看到最好的面為特徵的，即「樂觀的」。"}', 'optimistic outlook / cautiously optimistic', '[{"en":"She is optimistic about the future.","zh-TW":"她對未來持樂觀態度。"},{"en":"The report paints an optimistic picture.","zh-TW":"報告描繪了樂觀的景象。"}]', '{"noun":"optimism","noun2":"optimist","adverb":"optimistically"}', NULL, 4, 1457),
(1458, 'option', '/ˈɒpʃən/', 'noun', '{"zh-TW":["選項","期權"],"en":["a choice","right to buy/sell at set price"]}', '{"root":{"text":"opt","meaning":"choose (選)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'available options / stock option', '[{"en":"We have several options to consider.","zh-TW":"我們有幾個選項。"},{"en":"The company offers stock options.","zh-TW":"公司提供股票期權。"}]', '{"adjective":"optional","verb":"opt"}', NULL, 2, 1458),
(1459, 'oral', '/ˈɔːrəl/', 'adjective', '{"zh-TW":["口頭的"],"en":["spoken, not written"]}', '{"root":{"text":"or","meaning":"mouth (嘴)"},"suffix":{"text":"-al","meaning":"...的"}}', 'oral presentation / oral agreement', '[{"en":"The contract was only an oral agreement.","zh-TW":"合約只是口頭協議。"},{"en":"Each student must give an oral presentation.","zh-TW":"每人須做口頭報告。"}]', '{"adverb":"orally"}', NULL, 1, 1459),
(1460, 'orchestra', '/ˈɔːrkɪstrə/', 'noun', '{"zh-TW":["管弦樂團"],"en":["a large group of musicians playing various instruments"]}', '{"root":{"text":"orchestra","meaning":"dancing place (舞蹈場)"},"logic":"源自希臘語，原指劇場中合唱團的表演場地。"}', 'symphony orchestra / orchestra pit', '[{"en":"The orchestra performed Beethoven''s Fifth Symphony.","zh-TW":"管弦樂團演奏了貝多芬第五號交響曲。"},{"en":"She plays violin in the city orchestra.","zh-TW":"她在市立管弦樂團拉小提琴。"}]', '{"adjective":"orchestral","verb":"orchestrate"}', NULL, 3, 1460),
(1461, 'order', '/ˈɔːrdər/', 'noun', '{"zh-TW":["訂單","順序","命令"],"en":["a request for goods","sequence","instruction"]}', NULL, 'place an order / in order to / out of order', '[{"en":"We placed an order for 500 units.","zh-TW":"我們下了500件訂單。"},{"en":"The files are in alphabetical order.","zh-TW":"文件按字母排列。"}]', '{"adjective":"orderly","verb":"order"}', NULL, 2, 1461),
(1462, 'ordinance', '/ˈɔːrdɪnəns/', 'noun', '{"zh-TW":["條例；法令"],"en":["a law made by a city or town"]}', NULL, 'city ordinance / local ordinance', '[{"en":"The city passed a new ordinance.","zh-TW":"市政府通過了一項新條例。"},{"en":"It violates a local ordinance.","zh-TW":"這違反了地方條例。"}]', NULL, NULL, 3, 1462),
(1463, 'ordinary', '/ˈɔːrdɪneri/', 'adjective', '{"zh-TW":["普通的；平常的"],"en":["normal; not special"]}', '{"root":{"text":"ordin","meaning":"order (秩序)"},"suffix":{"text":"-ary","meaning":"...的"}}', 'ordinary people / out of the ordinary', '[{"en":"It was an ordinary day at the office.","zh-TW":"辦公室平常的一天。"},{"en":"Nothing out of the ordinary happened.","zh-TW":"沒什麼不尋常的事。"}]', '{"adverb":"ordinarily"}', NULL, 3, 1463),
(1464, 'organize', '/ˈɔːrɡənaɪz/', 'verb', '{"zh-TW":["組織；安排"],"en":["to plan and arrange"]}', '{"root":{"text":"organ","meaning":"instrument (工具)"},"suffix":{"text":"-ize","meaning":"使...化"}}', 'organize an event / well-organized', '[{"en":"She organized the annual conference.","zh-TW":"她組織了年度會議。"},{"en":"You need to organize your workspace.","zh-TW":"你需要整理工作空間。"}]', '{"noun":"organization, organizer","adjective":"organizational"}', NULL, 3, 1464),
(1465, 'orient', '/ˈɔːriɛnt/', 'verb', '{"zh-TW":["使適應；定向"],"en":["to help become familiar with"]}', '{"root":{"text":"ori","meaning":"rise (升起)"}}', 'orient oneself / market-oriented', '[{"en":"The program helps orient new employees.","zh-TW":"計劃幫助新員工適應。"},{"en":"The company is customer-oriented.","zh-TW":"公司以客戶為導向。"}]', '{"noun":"orientation","adjective":"oriented"}', NULL, 2, 1465),
(1466, 'orientation', '/ˌɔːriɛnˈteɪʃən/', 'noun', '{"zh-TW":["迎新；方向"],"en":["an introduction to a new situation"]}', NULL, 'orientation day / student orientation', '[{"en":"New student orientation is next Monday.","zh-TW":"新生迎新活動下週一舉行。"},{"en":"The orientation covers campus rules.","zh-TW":"迎新活動涵蓋了校規。"}]', NULL, NULL, 4, 1466),
(1467, 'origin', '/ˈɒrɪdʒɪn/', 'noun', '{"zh-TW":["起源；由來"],"en":["the beginning or source"]}', '{"root":{"text":"ori","meaning":"rise (升起)"}}', 'country of origin / origin of the problem', '[{"en":"What is the country of origin?","zh-TW":"原產國是哪裡？"},{"en":"We need to find the origin of the problem.","zh-TW":"需找到問題根源。"}]', '{"adjective":"original","adverb":"originally","verb":"originate"}', NULL, 2, 1467),
(1468, 'original', '/əˈrɪdʒɪnəl/', 'adjective', '{"zh-TW":["原始的","獨創的"],"en":["first; earliest","new and creative"]}', '{"root":{"text":"origin","meaning":"beginning"},"suffix":{"text":"-al","meaning":"...的"}}', 'original idea / original document', '[{"en":"Please submit the original documents.","zh-TW":"請提交原始文件。"},{"en":"She comes up with original ideas.","zh-TW":"她總能想出獨創想法。"}]', '{"noun":"originality","adverb":"originally","verb":"originate"}', NULL, 3, 1468),
(1469, 'otherwise', '/ˈʌðərwaɪz/', 'adverb', '{"zh-TW":["否則","在其他方面"],"en":["if not; or else","in other ways"]}', NULL, 'unless otherwise stated', '[{"en":"Submit by Friday; otherwise, it will be late.","zh-TW":"週五前提交；否則就遲了。"},{"en":"Unless otherwise stated, it applies to all.","zh-TW":"除非另有說明，適用於全部。"}]', NULL, NULL, 3, 1469),
(1470, 'outcome', '/ˈaʊtkʌm/', 'noun', '{"zh-TW":["結果；成果"],"en":["the result of an action"]}', '{"prefix":{"text":"out-","meaning":"外"},"root":{"text":"come","meaning":"來"}}', 'positive outcome / final outcome', '[{"en":"The outcome of the negotiation was favorable.","zh-TW":"談判結果有利。"},{"en":"We await the outcome of the vote.","zh-TW":"我們等待投票結果。"}]', NULL, NULL, 3, 1470),
(1471, 'outlet', '/ˈaʊtlet/', 'noun', '{"zh-TW":["暢貨中心；出口"],"en":["a store selling goods at reduced prices","an opening for something to pass through"]}', '{"prefix":{"text":"out-","meaning":"out (外)"},"root":{"text":"let","meaning":"allow (讓)"},"logic":"讓東西出去的地方，引申為暢貨中心。"}', 'factory outlet / outlet store', '[{"en":"She bought designer shoes at the outlet.","zh-TW":"她在暢貨中心買了名牌鞋。"},{"en":"There is a new outlet mall outside the city.","zh-TW":"城外有一座新的暢貨中心。"}]', NULL, NULL, 2, 1471),
(1472, 'outline', '/ˈaʊtlaɪn/', 'verb', '{"zh-TW":["概述；勾勒"],"en":["to describe main features"]}', '{"prefix":{"text":"out-","meaning":"外"},"root":{"text":"line","meaning":"線"}}', 'outline a plan / outline key points', '[{"en":"The CEO outlined the strategy for next year.","zh-TW":"執行長概述了明年策略。"},{"en":"Let me outline the main points.","zh-TW":"讓我概述要點。"}]', '{"noun":"outline"}', NULL, 3, 1472),
(1473, 'output', '/ˈaʊtpʊt/', 'noun', '{"zh-TW":["產量；輸出"],"en":["the amount produced"]}', '{"prefix":{"text":"out-","meaning":"外"},"root":{"text":"put","meaning":"放"}}', 'total output / increase output', '[{"en":"Factory output increased by 20%.","zh-TW":"工廠產量增加了20%。"},{"en":"The team''s output was impressive.","zh-TW":"團隊產出令人印象深刻。"}]', '{"verb":"output"}', NULL, 2, 1473),
(1474, 'outside', '/ˌaʊtˈsaɪd/', 'preposition', '{"zh-TW":["在…外面"],"en":["not inside; beyond"]}', NULL, 'outside the box / outside help', '[{"en":"We need to think outside the box.","zh-TW":"我們需要跳脫框架思考。"},{"en":"We may need outside help.","zh-TW":"我們可能需要外部幫助。"}]', '{"preposition":"outside","noun":"outsider","adjective":"outside"}', NULL, 3, 1474),
(1475, 'outsource', '/ˈaʊtsɔːrs/', 'verb', '{"zh-TW":["外包"],"en":["to hire an outside company to do work"]}', NULL, 'outsource production / outsource IT', '[{"en":"We outsource IT support to reduce costs.","zh-TW":"我們將IT支援外包以降低成本。"},{"en":"Many firms outsource manufacturing overseas.","zh-TW":"許多公司將製造外包到海外。"}]', '{"verb":"outsource","noun":"outsourcing"}', NULL, 3, 1475),
(1476, 'outstanding', '/aʊtˈstændɪŋ/', 'adjective', '{"zh-TW":["傑出的","未解決的"],"en":["excellent","not yet resolved"]}', '{"prefix":{"text":"out-","meaning":"超出"},"root":{"text":"standing","meaning":"站立"}}', 'outstanding performance / outstanding balance', '[{"en":"She received an award for outstanding performance.","zh-TW":"她因傑出表現獲獎。"},{"en":"There are outstanding invoices.","zh-TW":"有未付的發票。"}]', '{"adverb":"outstandingly"}', NULL, 4, 1476),
(1477, 'overall', '/ˌoʊvərˈɔːl/', 'adjective', '{"zh-TW":["整體的；全面的"],"en":["including everything; total"]}', '{"prefix":{"text":"over-","meaning":"全部"},"root":{"text":"all","meaning":"所有"}}', 'overall performance / overall cost', '[{"en":"The overall cost exceeded the budget.","zh-TW":"總成本超出預算。"},{"en":"Overall, results were satisfactory.","zh-TW":"總體而言結果令人滿意。"}]', '{"adverb":"overall"}', NULL, 3, 1477),
(1478, 'overcome', '/ˌoʊvərˈkʌm/', 'verb', '{"zh-TW":["克服","克服；戰勝"],"en":["to succeed in dealing with a problem","to succeed in dealing with difficulty"]}', '{"prefix":{"text":"over-","meaning":"over (越過)"},"root":{"text":"come","meaning":"come (到來)"},"logic":"越過困難而到達，即「克服」。"}', 'overcome obstacles / overcome challenges / overcome fear; overcome difficulties / overcome obstacles', '[{"en":"She overcame many obstacles to succeed.","zh-TW":"她克服了許多障礙才成功。"},{"en":"He is trying to overcome his fear of public speaking.","zh-TW":"他正在試圖克服對公開演講的恐懼。"},{"en":"She overcame many challenges.","zh-TW":"她克服了許多挑戰。"},{"en":"We must overcome these difficulties.","zh-TW":"我們必須克服這些困難。"}]', NULL, NULL, 3, 1478),
(1479, 'overhead', '/ˈoʊvərˌhɛd/', 'noun', '{"zh-TW":["管理費用；經常性開支"],"en":["ongoing business expenses not directly tied to production"]}', NULL, 'overhead costs / reduce overhead', '[{"en":"We need to reduce overhead costs.","zh-TW":"我們需要降低管理費用。"},{"en":"Rent is our biggest overhead expense.","zh-TW":"租金是我們最大的經常性開支。"}]', '{"noun":"overhead","adjective":"overhead"}', NULL, 3, 1479),
(1480, 'overlook', '/ˌoʊvərˈlʊk/', 'verb', '{"zh-TW":["忽略","俯瞰"],"en":["to fail to notice","to have a view over"]}', '{"prefix":{"text":"over-","meaning":"over"},"root":{"text":"look","meaning":"看"}}', 'overlook a detail / easily overlooked', '[{"en":"Don''t overlook the fine print.","zh-TW":"別忽略小字。"},{"en":"This detail was overlooked.","zh-TW":"這個細節被忽視了。"}]', NULL, NULL, 3, 1480),
(1481, 'overseas', '/ˌoʊvərˈsiːz/', 'adverb', '{"zh-TW":["海外的"],"en":["in a foreign country"]}', '{"prefix":{"text":"over-","meaning":"越過"},"root":{"text":"seas","meaning":"海洋"}}', 'overseas market / go overseas', '[{"en":"The company is expanding overseas.","zh-TW":"公司正在海外擴展。"},{"en":"Many graduates seek employment overseas.","zh-TW":"許多畢業生在海外求職。"}]', NULL, NULL, 3, 1481),
(1482, 'overtime', '/ˈoʊvərtaɪm/', 'noun', '{"zh-TW":["加班"],"en":["time worked beyond normal hours"]}', '{"prefix":{"text":"over-","meaning":"超過"},"root":{"text":"time","meaning":"時間"}}', 'work overtime / overtime pay', '[{"en":"Employees are paid extra for overtime.","zh-TW":"員工加班有額外報酬。"},{"en":"She works overtime to meet deadlines.","zh-TW":"她加班趕截止日期。"}]', NULL, NULL, 3, 1482),
(1483, 'overview', '/ˈoʊvərvjuː/', 'noun', '{"zh-TW":["概述；總覽"],"en":["a general summary"]}', '{"prefix":{"text":"over-","meaning":"全面"},"root":{"text":"view","meaning":"看"}}', 'brief overview / overview of the project', '[{"en":"The report provides an overview of trends.","zh-TW":"報告提供了趨勢概述。"},{"en":"Let me give a brief overview.","zh-TW":"讓我簡要概述。"}]', NULL, NULL, 3, 1483),
(1484, 'overwhelm', '/ˌoʊvərˈwɛlm/', 'verb', '{"zh-TW":["壓倒；使不知所措"],"en":["to be too much to deal with"]}', '{"prefix":{"text":"over-","meaning":"過度"},"root":{"text":"whelm","meaning":"submerge (淹沒)"}}', 'be overwhelmed by / overwhelming majority', '[{"en":"She was overwhelmed by the workload.","zh-TW":"她被工作量壓垮了。"},{"en":"The response was overwhelming.","zh-TW":"反應非常熱烈。"}]', '{"adjective":"overwhelming, overwhelmed","adverb":"overwhelmingly"}', NULL, 3, 1484),
(1485, 'owe', '/oʊ/', 'verb', '{"zh-TW":["欠","歸功於"],"en":["to need to pay back","to have because of help"]}', NULL, 'owe money / owe sb. a favor', '[{"en":"The company owes $5 million.","zh-TW":"公司欠五百萬美元。"},{"en":"I owe my success to my mentor.","zh-TW":"我的成功歸功於導師。"}]', NULL, NULL, 1, 1485),
(1486, 'pace', '/peɪs/', 'noun', '{"zh-TW":["步伐；速度"],"en":["the speed of movement or activity"]}', NULL, 'at a fast pace / keep pace with / set the pace', '[{"en":"The pace of technological change is rapid.","zh-TW":"技術變革的步伐很快。"},{"en":"We need to keep pace with competitors.","zh-TW":"我們需要跟上競爭對手。"}]', '{"verb":"pace"}', NULL, 1, 1486),
(1487, 'package', '/ˈpækɪdʒ/', 'noun', '{"zh-TW":["包裹","套裝；方案"],"en":["a wrapped object","a set of things offered together"]}', NULL, 'compensation package / package deal', '[{"en":"The package was delivered this morning.","zh-TW":"包裹今早送達了。"},{"en":"They offered an attractive compensation package.","zh-TW":"他們提供了優厚的薪酬方案。"}]', '{"verb":"package","noun":"packaging"}', NULL, 3, 1487),
(1488, 'packaging', '/ˈpækɪdʒɪŋ/', 'noun', '{"zh-TW":["包裝"],"en":["materials used to wrap or protect goods"]}', '{"root":{"text":"pack","meaning":"bundle (打包)"},"suffix":{"text":"-aging","meaning":"process of (過程)"},"logic":"打包的過程或材料，即「包裝」。"}', 'eco-friendly packaging / product packaging', '[{"en":"The packaging was damaged during shipping.","zh-TW":"包裝在運送過程中受損。"},{"en":"We use eco-friendly packaging materials.","zh-TW":"我們使用環保包裝材料。"}]', '{"verb":"package","noun":"package"}', NULL, 3, 1488),
(1489, 'page', '/peɪdʒ/', 'noun', '{"zh-TW":["頁面；網頁"],"en":["one side of a sheet of paper","a section of a website"]}', NULL, 'home page / on the same page', '[{"en":"Let''s make sure we are on the same page.","zh-TW":"讓我們確認彼此有共識。"},{"en":"Visit our web page for more details.","zh-TW":"請瀏覽我們的網頁了解更多。"}]', '{"noun":"page","noun2":"webpage"}', NULL, 1, 1489),
(1490, 'pain', '/peɪn/', 'noun', '{"zh-TW":["痛苦；疼痛"],"en":["physical suffering","mental distress"]}', NULL, 'pain point / no pain no gain', '[{"en":"We identified the customer''s pain points.","zh-TW":"我們找出了客戶的痛點。"},{"en":"No pain, no gain in business.","zh-TW":"商場上不吃苦就沒有收穫。"}]', '{"noun":"pain","adjective":"painful","adjective2":"painless","adverb":"painfully"}', NULL, 1, 1490),
(1491, 'paint', '/peɪnt/', 'verb', '{"zh-TW":["油漆；繪畫"],"en":["to apply color to a surface","to create a picture"]}', NULL, 'paint a picture / fresh paint', '[{"en":"Let me paint a picture of our vision.","zh-TW":"讓我描繪我們的願景。"},{"en":"The office walls need fresh paint.","zh-TW":"辦公室牆壁需要重新粉刷。"}]', '{"verb":"paint","noun":"paint","noun2":"painter","noun3":"painting"}', NULL, 2, 1491),
(1492, 'palette', '/ˈpælɪt/', 'noun', '{"zh-TW":["調色盤；色彩範圍"],"en":["a board for mixing paints","a range of colors used"]}', '{"root":{"text":"palette","meaning":"small blade (小板子)"},"logic":"源自法語，指畫家用來混合顏料的小板子。"}', 'color palette / artist''s palette', '[{"en":"The artist mixed colors on her palette.","zh-TW":"藝術家在調色盤上混合顏色。"},{"en":"The designer chose a warm color palette.","zh-TW":"設計師選擇了暖色調色盤。"}]', NULL, NULL, 3, 1492),
(1493, 'panel', '/ˈpænəl/', 'noun', '{"zh-TW":["專家小組","面板"],"en":["a group of experts","a flat surface"]}', NULL, 'panel discussion / solar panel / panel of judges', '[{"en":"A panel of experts discussed the issue.","zh-TW":"一組專家討論了這問題。"},{"en":"The company installed solar panels.","zh-TW":"公司安裝了太陽能板。"}]', '{"noun":"panelist"}', NULL, 2, 1493),
(1494, 'paper', '/ˈpeɪpər/', 'noun', '{"zh-TW":["紙；文件"],"en":["thin material for writing","a document"]}', NULL, 'on paper / white paper', '[{"en":"It looks good on paper.","zh-TW":"理論上看起來不錯。"},{"en":"We published a white paper on the topic.","zh-TW":"我們發表了一份相關白皮書。"}]', '{"noun":"paper","noun2":"paperwork","adjective":"paperless"}', NULL, 2, 1494),
(1495, 'paradigm', '/ˈpærədaɪm/', 'noun', '{"zh-TW":["典範；範式"],"en":["a typical example or model","a framework of thinking"]}', NULL, 'paradigm shift / new paradigm', '[{"en":"AI represents a paradigm shift in business.","zh-TW":"AI代表著商業的典範轉移。"},{"en":"We need a new paradigm for customer service.","zh-TW":"我們需要客戶服務的新典範。"}]', '{"noun":"paradigm","adjective":"paradigmatic"}', NULL, 3, 1495),
(1496, 'parallel', '/ˈpærəlɛl/', 'adjective', '{"zh-TW":["平行的","類似的"],"en":["extending in the same direction","similar"]}', '{"root":{"text":"para","meaning":"beside (旁邊)"},"suffix":{"text":"llel","meaning":"each other"}}', 'parallel to / run parallel / draw a parallel', '[{"en":"The two roads run parallel to each other.","zh-TW":"兩條路平行延伸。"},{"en":"There are parallels between the two cases.","zh-TW":"兩個案例有相似之處。"}]', '{"noun":"parallel","adverb":"parallelly"}', NULL, 3, 1496),
(1497, 'parameter', '/pəˈræmɪtər/', 'noun', '{"zh-TW":["參數；範圍"],"en":["a limit or boundary; a variable"]}', '{"root":{"text":"para","meaning":"beside"},"suffix":{"text":"meter","meaning":"measure (量)"}}', 'within the parameters / set parameters', '[{"en":"We must work within the parameters of the budget.","zh-TW":"我們必須在預算範圍內工作。"},{"en":"The manager set clear parameters for the project.","zh-TW":"經理為項目設定了明確的參數。"}]', NULL, NULL, 3, 1497),
(1498, 'parent', '/ˈpɛrənt/', 'noun', '{"zh-TW":["父母；母公司"],"en":["a mother or father","a company that owns another"]}', NULL, 'parent company / single parent', '[{"en":"The parent company is in Japan.","zh-TW":"母公司在日本。"},{"en":"Many employees are working parents.","zh-TW":"許多員工是在職父母。"}]', '{"noun":"parent","adjective":"parental","noun2":"parenthood"}', NULL, 2, 1498),
(1499, 'park', '/pɑːrk/', 'noun', '{"zh-TW":["公園；停車"],"en":["a public area for recreation","to leave a vehicle"]}', NULL, 'car park / industrial park', '[{"en":"The factory is in the industrial park.","zh-TW":"工廠在工業園區內。"},{"en":"Where can I park my car?","zh-TW":"我可以在哪裡停車？"}]', '{"noun":"park","verb":"park","noun2":"parking"}', NULL, 1, 1499);
