(1500, 'parole', '/pəˈroʊl/', 'noun', '{"zh-TW":["假釋"],"en":["early release from prison with conditions"]}', NULL, 'on parole / parole board', '[{"en":"He was released on parole.","zh-TW":"他被假釋出獄。"},{"en":"The parole board denied his request.","zh-TW":"假釋委員會拒絕了他的請求。"}]', NULL, NULL, 2, 1500),
(1501, 'participate', '/pɑːrˈtɪsɪpeɪt/', 'verb', '{"zh-TW":["參與","參加；參與"],"en":["to take part in an activity"]}', '{"root":{"text":"part","meaning":"part (部分)"},"suffix":{"text":"-icipate","meaning":"take (取得)"},"logic":"取得一份參與，即「參與」。"}', 'participate in / active participant; participate in / active participation', '[{"en":"Everyone is encouraged to participate in the discussion.","zh-TW":"鼓勵每個人參與討論。"},{"en":"Over 500 people participated in the survey.","zh-TW":"超過500人參與了調查。"},{"en":"All employees are encouraged to participate.","zh-TW":"鼓勵所有員工參與。"},{"en":"She participated in the training program.","zh-TW":"她參加了培訓計劃。"}]', '{"noun":"participation","noun2":"participant","adjective":"participatory"}', NULL, 4, 1501),
(1502, 'particular', '/pərˈtɪkjələr/', 'adjective', '{"zh-TW":["特定的","特別的"],"en":["specific","special; exceptional"]}', '{"root":{"text":"partic","meaning":"part (部分)"},"suffix":{"text":"-ular","meaning":"...的"}}', 'in particular / particular attention / nothing in particular', '[{"en":"Is there anything in particular you need?","zh-TW":"有什麼特別需要的嗎？"},{"en":"Pay particular attention to the deadline.","zh-TW":"請特別注意截止日期。"}]', '{"adverb":"particularly"}', NULL, 4, 1502),
(1503, 'partnership', '/ˈpɑːrtnərʃɪp/', 'noun', '{"zh-TW":["合夥；夥伴關係"],"en":["a relationship between partners"]}', '{"root":{"text":"partner","meaning":"夥伴"},"suffix":{"text":"-ship","meaning":"狀態"}}', 'form a partnership / business partnership / in partnership with', '[{"en":"The two companies formed a strategic partnership.","zh-TW":"兩家公司建立了策略夥伴關係。"},{"en":"We work in partnership with local suppliers.","zh-TW":"我們與當地供應商合作。"}]', '{"noun":"partner"}', NULL, 4, 1503),
(1504, 'party', '/ˈpɑːrti/', 'noun', '{"zh-TW":["派對；當事人"],"en":["a social gathering","a person or group in an agreement"]}', NULL, 'third party / office party', '[{"en":"We use a third-party vendor.","zh-TW":"我們使用第三方供應商。"},{"en":"The office party is next Friday.","zh-TW":"公司派對在下週五。"}]', '{"noun":"party"}', NULL, 2, 1504),
(1505, 'pass', '/pæs/', 'verb', '{"zh-TW":["通過；傳遞"],"en":["to go by","to hand over"]}', NULL, 'pass a test / pass along', '[{"en":"She passed the certification exam.","zh-TW":"她通過了認證考試。"},{"en":"Please pass this information along.","zh-TW":"請將這個消息轉達。"}]', '{"verb":"pass","noun":"pass","noun2":"passage","noun3":"passenger"}', NULL, 1, 1505),
(1506, 'passionate', '/ˈpæʃənət/', 'adjective', '{"zh-TW":["熱情的；熱烈的"],"en":["showing or caused by strong feelings"]}', '{"root":{"text":"passion","meaning":"suffer/feel (承受/感受)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"具有強烈感受的，即「熱情的」。"}', 'passionate about / passionate speech', '[{"en":"He is passionate about environmental protection.","zh-TW":"他對環境保護充滿熱情。"},{"en":"She gave a passionate speech about equality.","zh-TW":"她發表了一場關於平等的激昂演說。"}]', '{"noun":"passion","adverb":"passionately"}', NULL, 4, 1506),
(1507, 'past', '/pæst/', 'noun', '{"zh-TW":["過去"],"en":["the time before now"]}', NULL, 'in the past / past experience', '[{"en":"In the past, we used a different system.","zh-TW":"過去我們使用不同的系統。"},{"en":"Her past experience is very relevant.","zh-TW":"她過去的經驗非常相關。"}]', '{"noun":"past","adjective":"past","preposition":"past"}', NULL, 1, 1507),
(1508, 'patent', '/ˈpætənt/', 'noun', '{"zh-TW":["專利"],"en":["an official right to be the only maker of an invention","an official right to an invention"]}', '{"root":{"text":"pat","meaning":"open (公開)"}}', 'file a patent / patent pending; file a patent / patent application / patent holder', '[{"en":"She filed a patent for her invention.","zh-TW":"她為她的發明申請了專利。"},{"en":"The patent expires next year.","zh-TW":"專利明年到期。"},{"en":"The company filed a patent for the new design.","zh-TW":"公司為新設計申請了專利。"}]', '{"verb":"patent","adjective":"patented"}', NULL, 2, 1508),
(1509, 'path', '/pæθ/', 'noun', '{"zh-TW":["道路；途徑"],"en":["a way or track","a course of action"]}', NULL, 'career path / on the right path', '[{"en":"What is your career path?","zh-TW":"你的職涯路徑是什麼？"},{"en":"We are on the right path to success.","zh-TW":"我們在通往成功的正確路上。"}]', '{"noun":"path","noun2":"pathway"}', NULL, 1, 1509),
(1510, 'patient', '/ˈpeɪʃənt/', 'adjective', '{"zh-TW":["有耐心的；病人","有耐心的"],"en":["able to wait calmly","a person receiving medical care","able to wait without becoming annoyed"]}', '{"root":{"text":"pati","meaning":"suffer/endure (承受)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"能承受等待的，即「有耐心的」。"}', 'be patient / patient care; be patient / patient with', '[{"en":"Please be patient; we are working on it.","zh-TW":"請有耐心，我們正在處理中。"},{"en":"Patient satisfaction is our priority.","zh-TW":"病患滿意度是我們的首要任務。"},{"en":"Please be patient while we process your request.","zh-TW":"請耐心等候我們處理您的要求。"},{"en":"Good teachers are patient with students.","zh-TW":"好老師對學生有耐心。"}]', '{"adjective":"patient","noun":"patient","noun2":"patience","adjective2":"impatient","adverb":"patiently"}', NULL, 3, 1510),
(1511, 'patron', '/ˈpeɪtrən/', 'noun', '{"zh-TW":["顧客；贊助人"],"en":["a customer; a supporter"]}', '{"root":{"text":"patr","meaning":"father (父親)"}}', 'regular patron / patron of the arts', '[{"en":"The restaurant values its regular patrons.","zh-TW":"餐廳重視常客。"},{"en":"She is a well-known patron of the arts.","zh-TW":"她是知名的藝術贊助人。"}]', '{"noun":"patronage","verb":"patronize"}', NULL, 2, 1511),
(1512, 'patronage', '/ˈpætrənɪdʒ/', 'noun', '{"zh-TW":["惠顧；贊助"],"en":["regular custom to a business; support"]}', '{"root":{"text":"patr","meaning":"father (父親)"},"suffix":{"text":"-age","meaning":"行為"}}', 'thank you for your patronage / patronage of the arts', '[{"en":"Thank you for your continued patronage.","zh-TW":"感謝您持續的惠顧。"},{"en":"The museum relies on corporate patronage.","zh-TW":"博物館依靠企業贊助。"}]', '{"noun":"patron","verb":"patronize"}', NULL, 3, 1512),
(1513, 'pattern', '/ˈpætərn/', 'noun', '{"zh-TW":["模式；圖案"],"en":["a regular form or order"]}', NULL, 'behavior pattern / follow a pattern / pattern of growth', '[{"en":"We noticed a pattern in customer complaints.","zh-TW":"我們注意到客訴的模式。"},{"en":"Sales follow a seasonal pattern.","zh-TW":"銷售遵循季節性模式。"}]', '{"adjective":"patterned"}', NULL, 3, 1513),
(1514, 'pause', '/pɔːz/', 'verb', '{"zh-TW":["暫停"],"en":["to stop briefly"]}', NULL, 'pause for a moment / without pause', '[{"en":"Let''s pause the meeting for a short break.","zh-TW":"讓我們暫停會議休息一下。"},{"en":"He paused before answering the question.","zh-TW":"他回答前停頓了一下。"}]', '{"noun":"pause"}', NULL, 2, 1514),
(1515, 'pay', '/peɪ/', 'verb', '{"zh-TW":["支付；薪資"],"en":["to give money for something","money received for work"]}', NULL, 'pay raise / pay off', '[{"en":"The investment will pay off in the long run.","zh-TW":"這項投資從長遠來看會有回報。"},{"en":"She asked for a pay raise.","zh-TW":"她要求加薪。"}]', '{"verb":"pay","noun":"pay","noun2":"payment","noun3":"payroll","adjective":"payable"}', NULL, 1, 1515),
(1516, 'peace', '/piːs/', 'noun', '{"zh-TW":["和平；平靜"],"en":["freedom from disturbance","a state of calm"]}', NULL, 'peace of mind / keep the peace', '[{"en":"Insurance gives you peace of mind.","zh-TW":"保險讓你安心。"},{"en":"We want to keep the peace in the office.","zh-TW":"我們希望維持辦公室的和諧。"}]', '{"noun":"peace","adjective":"peaceful","adverb":"peacefully"}', NULL, 2, 1516),
(1517, 'peak', '/piːk/', 'noun', '{"zh-TW":["高峰；頂點"],"en":["the highest point"]}', NULL, 'peak season / reach a peak / peak performance', '[{"en":"Sales reached their peak in December.","zh-TW":"銷售在十二月達到高峰。"},{"en":"Peak hours are from 8 to 10 AM.","zh-TW":"高峰時段是早上8到10點。"}]', '{"adjective":"peak","verb":"peak"}', NULL, 1, 1517),
(1518, 'penalty', '/ˈpɛnəlti/', 'noun', '{"zh-TW":["罰款；處罰"],"en":["a punishment for breaking a rule"]}', '{"root":{"text":"pen","meaning":"punish (懲罰)"},"suffix":{"text":"-alty","meaning":"狀態"}}', 'pay a penalty / penalty clause / impose a penalty', '[{"en":"Late payment will incur a penalty.","zh-TW":"逾期付款將產生罰款。"},{"en":"The penalty for breach of contract is severe.","zh-TW":"違約的處罰很嚴重。"}]', '{"verb":"penalize","adjective":"penal"}', NULL, 3, 1518),
(1519, 'pending', '/ˈpɛndɪŋ/', 'adjective', '{"zh-TW":["待定的；未決的"],"en":["awaiting decision; not yet resolved"]}', '{"root":{"text":"pend","meaning":"hang (懸掛)"}}', 'pending approval / pending investigation', '[{"en":"The application is still pending.","zh-TW":"申請仍在審核中。"},{"en":"Pending approval, we will proceed.","zh-TW":"待批准後我們將繼續。"}]', NULL, NULL, 3, 1519),
(1520, 'pension', '/ˈpɛnʃən/', 'noun', '{"zh-TW":["退休金"],"en":["regular payment after retirement"]}', '{"root":{"text":"pens","meaning":"pay (支付)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'pension plan / pension fund / retirement pension', '[{"en":"The company offers a generous pension plan.","zh-TW":"公司提供優厚的退休金計劃。"},{"en":"She retired with a full pension.","zh-TW":"她領取全額退休金退休。"}]', '{"noun":"pensioner"}', NULL, 3, 1520),
(1521, 'people', '/ˈpiːpəl/', 'noun', '{"zh-TW":["人們"],"en":["human beings in general"]}', NULL, 'people skills / people management', '[{"en":"Good people skills are essential for managers.","zh-TW":"良好的人際交往能力對管理者至關重要。"},{"en":"We put people first.","zh-TW":"我們以人為本。"}]', '{"noun":"people","noun2":"person","adjective":"personal"}', NULL, 2, 1521),
(1522, 'perceive', '/pərˈsiːv/', 'verb', '{"zh-TW":["感知；察覺","認為"],"en":["to become aware of","to regard as"]}', '{"prefix":{"text":"per-","meaning":"through"},"root":{"text":"ceive","meaning":"take (拿取)"}}', 'perceive as / perceive a threat / widely perceived', '[{"en":"The change was perceived as positive.","zh-TW":"這變化被認為是正面的。"},{"en":"Customers perceive our brand as reliable.","zh-TW":"客戶認為我們品牌可靠。"}]', '{"noun":"perception","adjective":"perceptive"}', NULL, 3, 1522),
(1523, 'percent', '/pərˈsɛnt/', 'noun', '{"zh-TW":["百分比"],"en":["one part in every hundred"]}', '{"prefix":{"text":"per-","meaning":"for each"},"root":{"text":"cent","meaning":"hundred (百)"}}', '50 percent / percent increase / percentage', '[{"en":"Sales increased by 15 percent.","zh-TW":"銷售增加了15%。"},{"en":"Only a small percent of applicants are accepted.","zh-TW":"只有少數申請者被錄取。"}]', '{"noun":"percentage"}', NULL, 3, 1523),
(1524, 'perform', '/pərˈfɔːrm/', 'verb', '{"zh-TW":["表演；執行","執行；履行","表現"],"en":["to carry out an action","to entertain an audience","to carry out a task","to function or do well"]}', '{"prefix":{"text":"per-","meaning":"through (通過)"},"root":{"text":"form","meaning":"provide (提供)"},"logic":"徹底提供（表演），即「表演」。"}', 'perform a task / perform on stage; perform a task / perform well / perform duties', '[{"en":"The band will perform live tonight.","zh-TW":"樂團今晚將現場表演。"},{"en":"She performed the surgery successfully.","zh-TW":"她成功地執行了手術。"},{"en":"The system performs well under pressure.","zh-TW":"系統在壓力下表現良好。"},{"en":"Employees must perform their duties efficiently.","zh-TW":"員工必須有效履行職責。"}]', '{"noun":"performance","noun2":"performer"}', NULL, 3, 1524),
(1525, 'performance', '/pərˈfɔːrməns/', 'noun', '{"zh-TW":["表演；表現"],"en":["an act of presenting entertainment; how well one does"]}', NULL, 'live performance / job performance', '[{"en":"The performance received great reviews.","zh-TW":"這場表演獲得了極好的評價。"},{"en":"His job performance improved greatly.","zh-TW":"他的工作表現大幅改善。"}]', '{"verb":"perform","noun2":"performer"}', NULL, 4, 1525),
(1526, 'period', '/ˈpɪriəd/', 'noun', '{"zh-TW":["期間；時期"],"en":["a length of time"]}', '{"root":{"text":"peri","meaning":"around (周圍)"}}', 'during this period / trial period / period of time', '[{"en":"Sales declined during this period.","zh-TW":"這段期間銷售下降。"},{"en":"The trial period is 90 days.","zh-TW":"試用期為90天。"}]', '{"adjective":"periodic, periodical","adverb":"periodically"}', NULL, 2, 1526),
(1527, 'permanent', '/ˈpɜːrmənənt/', 'adjective', '{"zh-TW":["永久的；長期的"],"en":["lasting forever or for a long time"]}', '{"prefix":{"text":"per-","meaning":"through"},"root":{"text":"man","meaning":"remain (留下)"},"suffix":{"text":"-ent","meaning":"...的"}}', 'permanent position / permanent damage / permanent residence', '[{"en":"She was offered a permanent position.","zh-TW":"她獲得了正式職位。"},{"en":"The damage may be permanent.","zh-TW":"損害可能是永久的。"}]', '{"adverb":"permanently","noun":"permanence"}', NULL, 3, 1527),
(1528, 'permit', '/pərˈmɪt/', 'verb', '{"zh-TW":["允許；許可"],"en":["to give permission for something","to allow something"]}', '{"prefix":{"text":"per-","meaning":"through (通過)"},"root":{"text":"mit","meaning":"send (送)"},"logic":"讓其通過放行，即「允許」。"}', 'permit access / weather permitting / work permit; permit sb. to do / work permit / building permit', '[{"en":"Photography is not permitted inside the museum.","zh-TW":"博物館內不允許拍照。"},{"en":"The law does not permit this activity.","zh-TW":"法律不允許此活動。"},{"en":"Employees are not permitted to use personal phones.","zh-TW":"員工不允許使用個人手機。"},{"en":"You need a permit to park here.","zh-TW":"你需要許可證才能停這裡。"}]', '{"noun":"permit","noun2":"permission","adjective":"permissible"}', NULL, 2, 1528),
(1529, 'persist', '/pərˈsɪst/', 'verb', '{"zh-TW":["堅持；持續"],"en":["to continue firmly; to last"]}', '{"prefix":{"text":"per-","meaning":"through"},"root":{"text":"sist","meaning":"stand (站立)"}}', 'persist in / persist with / if problems persist', '[{"en":"If the problem persists, contact support.","zh-TW":"如問題持續，請聯繫支援。"},{"en":"She persisted in her efforts despite setbacks.","zh-TW":"儘管受挫她仍堅持努力。"}]', '{"noun":"persistence","adjective":"persistent","adverb":"persistently"}', NULL, 3, 1529),
(1530, 'personal', '/ˈpɜːrsənəl/', 'adjective', '{"zh-TW":["個人的；私人的"],"en":["relating to a particular person"]}', '{"root":{"text":"person","meaning":"person (人)"},"suffix":{"text":"-al","meaning":"...的"}}', 'personal information / personal opinion / personal belongings', '[{"en":"Do not share personal information online.","zh-TW":"不要在網上分享個人資訊。"},{"en":"This is my personal opinion.","zh-TW":"這是我個人意見。"}]', '{"noun":"personality","adverb":"personally","verb":"personalize"}', NULL, 3, 1530),
(1531, 'personnel', '/ˌpɜːrsəˈnɛl/', 'noun', '{"zh-TW":["人員；員工"],"en":["the people employed in an organization"]}', '{"root":{"text":"person","meaning":"person (人)"}}', 'personnel department / key personnel / military personnel', '[{"en":"All personnel must attend the training.","zh-TW":"所有人員必須參加培訓。"},{"en":"The personnel department handles hiring.","zh-TW":"人事部門處理招聘。"}]', NULL, NULL, 3, 1531),
(1532, 'perspective', '/pərˈspektɪv/', 'noun', '{"zh-TW":["觀點；角度","觀點；視角"],"en":["a particular way of viewing things","a way of thinking about something"]}', '{"prefix":{"text":"per-","meaning":"through (透過)"},"root":{"text":"spect","meaning":"look (看)"},"suffix":{"text":"-ive","meaning":"relating to (相關的)"},"logic":"透過某角度來看，即「觀點」。"}', 'from my perspective / gain perspective / new perspective; from a different perspective / put into perspective / gain perspective; from my perspective / gain a new perspective / put in perspective', '[{"en":"From my perspective, the plan makes sense.","zh-TW":"從我的角度來看，這個計畫合理。"},{"en":"Travel gives you a new perspective on life.","zh-TW":"旅行給你新的人生觀點。"},{"en":"Try to see it from the customer''s perspective.","zh-TW":"試從客戶角度看。"},{"en":"The report puts the data into perspective.","zh-TW":"報告讓數據更有脈絡。"},{"en":"From a financial perspective, the deal is good.","zh-TW":"從財務角度看，這筆交易不錯。"},{"en":"Travel helps you gain new perspectives.","zh-TW":"旅行幫助你獲得新的觀點。"}]', NULL, NULL, 4, 1532),
(1533, 'persuade', '/pərˈsweɪd/', 'verb', '{"zh-TW":["說服"],"en":["to cause someone to do or believe something"]}', '{"prefix":{"text":"per-","meaning":"thoroughly"},"root":{"text":"suade","meaning":"advise (勸)"}}', 'persuade sb. to do / be persuaded', '[{"en":"She persuaded the board to approve the budget.","zh-TW":"她說服董事會批准預算。"},{"en":"I was persuaded by his argument.","zh-TW":"我被他的論點說服了。"}]', '{"noun":"persuasion","adjective":"persuasive","adverb":"persuasively"}', NULL, 3, 1533),
(1534, 'pessimistic', '/ˌpesɪˈmɪstɪk/', 'adjective', '{"zh-TW":["悲觀的"],"en":["tending to see the worst aspect of things"]}', '{"root":{"text":"pessim","meaning":"worst (最壞)"},"suffix":{"text":"-istic","meaning":"characterized by (以…為特徵)"},"logic":"以看到最壞面為特徵的，即「悲觀的」。"}', 'pessimistic view / pessimistic about', '[{"en":"He has a pessimistic view of the economy.","zh-TW":"他對經濟持悲觀看法。"},{"en":"Don''t be so pessimistic about everything.","zh-TW":"不要對所有事都那麼悲觀。"}]', '{"noun":"pessimism","noun2":"pessimist"}', NULL, 4, 1534),
