(1537, 'phenomenon', '/fɪˈnɒmɪnən/', 'noun', '{"zh-TW":["現象"],"en":["a fact or situation that is observed"]}', '{"root":{"text":"pheno","meaning":"appear (出現)"}}', 'natural phenomenon / social phenomenon', '[{"en":"This is a common phenomenon in the industry.","zh-TW":"這是行業中的常見現象。"},{"en":"Remote work has become a global phenomenon.","zh-TW":"遠程工作已成為全球現象。"}]', '{"adjective":"phenomenal","adverb":"phenomenally"}', NULL, 4, 1537),
