(1540, 'piece', '/piːs/', 'noun', '{"zh-TW":["一片；一件"],"en":["a part of something","a single item"]}', NULL, 'a piece of advice / fall into place', '[{"en":"Let me give you a piece of advice.","zh-TW":"讓我給你一個建議。"},{"en":"Everything is falling into place.","zh-TW":"一切都步入正軌了。"}]', '{"noun":"piece"}', NULL, 2, 1540),
